from AlgorithmImports import *
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data):
        bars = data.Bars

        has_all_bars = all(bars.ContainsKey(symbol) for symbol in self.symbols)

        spy_close = None
        aapl_close = None

        if bars.ContainsKey(self.spy):
            spy_close = float(bars[self.spy].Close)

        if bars.ContainsKey(self.aapl):
            aapl_close = float(bars[self.aapl].Close)

        current_spy_sma = None
        if self.spy_sma.IsReady:
            current_spy_sma = float(self.spy_sma.Current.Value)

        if aapl_close is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        spy_crosses_above = False
        spy_crosses_below = False

        if (
            spy_close is not None
            and current_spy_sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            spy_crosses_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > current_spy_sma
            )
            spy_crosses_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < current_spy_sma
            )

        ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_aapl_close is not None
        )

        if has_all_bars and not self.IsWarmingUp and ready:
            aapl_rsi_above_60 = float(self.aapl_rsi.Current.Value) > 60
            aapl_buy_reason = self.aapl_red_streak >= 1

            if (
                self.strategy_a_lot > 0
                and not self.strategy_a_pending
                and spy_crosses_below
            ):
                self._submit_order(
                    "A",
                    self.spy,
                    -self.strategy_a_lot,
                    "A_SELL"
                )

            if (
                self.strategy_b_lot > 0
                and not self.strategy_b_pending
                and aapl_rsi_above_60
            ):
                self._submit_order(
                    "B",
                    self.aapl,
                    -self.strategy_b_lot,
                    "B_SELL"
                )

            if (
                self.strategy_a_lot == 0
                and not self.strategy_a_pending
                and spy_crosses_above
            ):
                quantity = int(
                    math.floor(
                        0.40
                        * float(self.Portfolio.TotalPortfolioValue)
                        / spy_close
                    )
                )
                if quantity > 0:
                    self._submit_order(
                        "A",
                        self.spy,
                        quantity,
                        "A_BUY"
                    )

            if (
                self.strategy_b_lot == 0
                and not self.strategy_b_pending
                and aapl_buy_reason
                and float(self.Portfolio.Cash) >= 20000
            ):
                quantity = int(math.floor(20000 / aapl_close))
                if quantity > 0:
                    self._submit_order(
                        "B",
                        self.aapl,
                        quantity,
                        "B_BUY"
                    )

        if spy_close is not None:
            self.previous_spy_close = spy_close

        if current_spy_sma is not None:
            self.previous_spy_sma = current_spy_sma

        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

    def _submit_order(self, strategy, symbol, quantity, tag):
        if strategy == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False
            return

        if ticket.Status not in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if order.Tag == "A_BUY":
                self.strategy_a_lot += fill_quantity
            elif order.Tag == "A_SELL":
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )
            elif order.Tag == "B_BUY":
                self.strategy_b_lot += fill_quantity
            elif order.Tag == "B_SELL":
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if order.Tag.startswith("A_"):
                self.strategy_a_pending = False
            elif order.Tag.startswith("B_"):
                self.strategy_b_pending = False
